import { DataTable, DataTableContent, DataTablePagination, ColumnDef, useDataTable } from "@traxion-global/design-system/react";
import { useEffect, useState } from "react";

interface User {
  id: number;
  firstName: string;
  email: string;
}

const columns: ColumnDef<User>[] = [
  { header: "ID", accessorKey: "id", size: 50 },
  { header: "Name", accessorKey: "firstName" },
  { header: "Email", accessorKey: "email" },
];

export default function UsersTable() {
  const [data, setData] = useState<User[]>([]);
  const [pageCount, setPageCount] = useState(0);
  const tableState = useDataTable({ pageSize: 10 });

  useEffect(() => {
    const { pageIndex, pageSize } = tableState.pagination;
    fetch(`/api/users?limit=${pageSize}&skip=${pageIndex * pageSize}`)
      .then((res) => res.json())
      .then((result) => {
        setData(result.users);
        setPageCount(Math.ceil(result.total / pageSize));
      });
  }, [tableState.pagination.pageIndex, tableState.pagination.pageSize]);

  return (
    <DataTable
      data={data}
      columns={columns}
      pageCount={pageCount}
      {...tableState}
    >
      <DataTableContent />
      <DataTablePagination />
    </DataTable>
  );
}

