import {
  DataTable, DataTableContent, DataTablePagination, DataTableToolbar,
  ColumnDef, useDataTable, Input, useDebouncedCallback, Button
} from "@traxion-global/design-system/react";
import { X } from "lucide-react";

export default function FilterableTable() {
  const [data, setData] = useState<User[]>([]);
  const [pageCount, setPageCount] = useState(0);
  const [searchValue, setSearchValue] = useState("");
  const tableState = useDataTable({ pageSize: 10 });

  useEffect(() => {
    const { pageIndex, pageSize } = tableState.pagination;
    const filters = tableState.columnFilters
      .map(f => `key=${f.id}&value=${f.value}`).join("&");
    const url = filters
      ? `/api/users/filter?limit=${pageSize}&skip=${pageIndex * pageSize}&${filters}`
      : `/api/users?limit=${pageSize}&skip=${pageIndex * pageSize}`;
    fetch(url).then(res => res.json()).then(result => {
      setData(result.users);
      setPageCount(Math.ceil(result.total / pageSize));
    });
  }, [tableState.pagination.pageIndex, tableState.pagination.pageSize, tableState.columnFilters]);

  // Reset page when filters change
  useEffect(() => {
    tableState.setPagination(prev => ({ ...prev, pageIndex: 0 }));
  }, [tableState.columnFilters]);

  const debouncedSetFilter = useDebouncedCallback((value: string) => {
    tableState.setColumnFilters(prev => {
      const without = prev.filter(f => f.id !== "id");
      return value ? [...without, { id: "id", value }] : without;
    });
  }, 300);

  return (
    <DataTable columns={columns} data={data} pageCount={pageCount} {...tableState}>
      <DataTableToolbar>
        <Input
          placeholder="Search by ID"
          value={searchValue}
          onChange={(e) => {
            setSearchValue(e.target.value);
            debouncedSetFilter(e.target.value);
          }}
          className="h-8 w-[200px]"
        />
        {tableState.columnFilters.length > 0 && (
          <Button variant="outline" onClick={() => {
            tableState.setColumnFilters([]);
            setSearchValue("");
          }}>
            <X className="mr-2 h-4 w-4" /> Clear filters
          </Button>
        )}
      </DataTableToolbar>
      <DataTableContent />
      <DataTablePagination />
    </DataTable>
  );
}

