import {
  DataTable, DataTableContent, DataTablePagination, DataTableToolbar,
  DataTableViewOptions, DataTableColumnHeader, ColumnDef, useDataTable,
  Checkbox, Input, Button, useDebouncedCallback, Badge
} from "@traxion-global/design-system/react";
import { Pencil, Trash, X } from "lucide-react";

export default function FullFeaturedTable() {
  const [data, setData] = useState<UserData[]>([]);
  const [pageCount, setPageCount] = useState(0);
  const [isLoading, setIsLoading] = useState(true);
  const [rowSelection, setRowSelection] = useState({});
  const [searchValue, setSearchValue] = useState("");
  const tableState = useDataTable({ pageSize: 10 });

  const debouncedSetFilter = useDebouncedCallback((value: string) => {
    tableState.setColumnFilters(prev => {
      const without = prev.filter(f => f.id !== "ID");
      return value ? [...without, { id: "ID", value }] : without;
    });
  }, 300);

  useEffect(() => {
    setIsLoading(true);
    fetchUsers(tableState).then(result => {
      setData(result.users);
      setPageCount(Math.ceil(result.total / tableState.pagination.pageSize));
      setIsLoading(false);
    });
  }, [
    tableState.pagination.pageIndex,
    tableState.pagination.pageSize,
    tableState.sorting,
    tableState.columnFilters,
  ]);

  useEffect(() => {
    tableState.setPagination(prev => ({ ...prev, pageIndex: 0 }));
  }, [tableState.columnFilters]);

  return (
    <DataTable
      data={data}
      columns={columns}
      pageCount={pageCount}
      isLoading={isLoading}
      enableRowSelection
      rowSelection={rowSelection}
      onRowSelectionChange={setRowSelection}
      enableColumnReordering
      {...tableState}
    >
      <DataTableToolbar>
        <Input
          placeholder="Search by ID"
          value={searchValue}
          onChange={(e) => {
            setSearchValue(e.target.value);
            debouncedSetFilter(e.target.value);
          }}
          className="h-8 w-[200px]"
        />
        {tableState.columnFilters.length > 0 && (
          <Button variant="outline" onClick={() => {
            tableState.setColumnFilters([]);
            setSearchValue("");
          }} className="h-8 px-2 lg:px-3">
            <X className="mr-2 h-4 w-4" /> Clear filters
          </Button>
        )}
        {Object.keys(rowSelection).length > 0 && (
          <Button variant="destructive" className="h-8 px-2 lg:px-3">
            Delete selected ({Object.keys(rowSelection).length})
          </Button>
        )}
        <DataTableViewOptions />
      </DataTableToolbar>
      <DataTableContent />
      {!isLoading && <DataTablePagination />}
    </DataTable>
  );
}
